import logo from './logo.svg';
import React, { useState } from 'react'; // useState import 추가
import { Header } from './6주차 practice/Header';
import { Nav} from './6주차 practice/Nav';
import { Create} from './6주차 practice/Create';
import './App.css'

function App() {
  // 3. 상태(State) 관리 추가
  const [topics, setTopics] = useState([
    { id: 1, title: 'HTML', body: 'HTML is ...' },
    { id: 2, title: 'CSS', body: 'CSS is ...' },
    { id: 3, title: 'JS', body: 'JavaScript is ...' },
    { id: 4, title: 'React', body: 'React is ...' },
  ]);

  const [nextId, setNextId] = useState(topics.length + 1); // topics 배열의 다음 id

  // 4. 항목 추가 함수 구현
  const handleCreateTopic = (title, body) => {
    const newTopic = { id: nextId, title: title, body: body };
    setTopics([...topics, newTopic]); // 새 항목을 기존 topics 배열에 추가
    setNextId(nextId + 1); // 다음 id 증가
  };

  // 5. JSX 구조 변경
  return (
    <div className="container"> {/* App.css에서 정의할 클래스명 (기존 "App" 클래스명 유지해도 무방) */}
      {/* Header 컴포넌트에 title prop 전달 */}
      <Header title="ERICA x React Props State" />
      {/* Nav 컴포넌트에 topics prop 전달 */}
      <Nav topics={topics} />
      {/* Create 컴포넌트를 렌더링하고 onCreate prop으로 함수 전달 */}
      <div className="content-area"> {/* App.css에서 정의할 클래스명 */}
        <Create onCreate={handleCreateTopic} />
      </div>
    </div>
  );
}

export default App;
